mapper.select:
select name from course
is_in_progress = #{isInProgressForAdmin}
order by start_date desc

select tl.id,tl.course_id,tl.training_date, tl.instructor_id
from training_log tl
inner join course c
on tl.course_id = c.id
where tl.instructor_id = #{instructorId}

  and c.name = #{courseName}
